<section class="operator-bottom operator-bottom-single"><div><h2>ACTIVE QUEUES FOR SELECTED SERVICE</h2><div class="operator-list" id="list"><?php foreach($current as $t):?><article class="queue-card" data-id="<?=e($t['id'])?>" data-service-id="<?=e($t['service_id'])?>" data-counter-id="<?=e($t['counter_id']??'')?>" data-ticket-number="<?=e($t['ticket_number'])?>" data-service-name="<?=e($t['service_name'])?>"><div><span class="badge"><?=e($t['status'])?></span><strong><?=e($t['ticket_number'])?></strong><small><?=e($t['service_name'])?> · <?=e($t['counter_name']??'-')?></small></div><div class="queue-actions"><button data-action="recall">Call Again</button><button data-action="serve">Serve</button><button data-action="complete">Complete</button><button data-action="skip" class="secondary">Skip</button><button data-action="cancel" class="danger">Cancel</button></div></article><?php endforeach?></div></div></section></main>
<details class="operator-notification-panel"><summary>🔔 Queue Notifications</summary><form id="notification-settings" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label class="media-check"><input type="checkbox" name="enabled" <?=$notificationSettings['enabled']?'checked':''?>> Enable new-queue alerts</label><label>Sound<select name="sound_type"><option value="chime" <?=$notificationSettings['sound_type']==='chime'?'selected':''?>>Chime</option><option value="bell" <?=$notificationSettings['sound_type']==='bell'?'selected':''?>>Bell</option><option value="beep" <?=$notificationSettings['sound_type']==='beep'?'selected':''?>>Beep</option><option value="custom" <?=$notificationSettings['sound_type']==='custom'?'selected':''?>>Uploaded custom sound</option></select></label><label>Volume<input type="range" name="volume" min="0" max="1" step="0.05" value="<?=e($notificationSettings['volume'])?>"></label><label>Upload MP3/WAV/OGG<input type="file" name="sound_file" accept="audio/mpeg,audio/wav,audio/ogg"></label><div class="notification-actions"><button type="button" id="test-notification">Test sound</button><button type="submit">Save</button></div><small id="notification-status">Alerts apply only to your assigned services.</small></form></details><div id="queue-toast" class="queue-toast"></div>
